import os

def word_count(path):
    words = set()
    for file in os.listdir(path):
        with open(os.path.join(path, file), 'r') as f:
            for line in f:
                words.add(line.strip())

    counts = {}
    for word in words:
        counts[word] = word_count(os.path.join(path, word))

    top_5 = sorted(counts.items(), key=lambda t: t[1], reverse=True)[:5]
    return top_5[0][0] for top_5 in top_5[:5]

def word_count_file(file):
    with open(file, 'r') as f:
        for line in f:
            words = line.split()
            word_count(os.path.join(os.path.dirname(file), words[0]))

if __name__ == '__main__':
